   /**
    * f0 -> Identifier()
    * f1 -> "="
    * f2 -> Expression()
    * f3 -> ";"
    */
   public R visit(AssignmentStatement n, A argu) {
      R _ret=null;
      String type_rhs;
      Lambda_exp lambda_exp = new Lambda_exp();
      
      String type_lhs = (String)n.f0.accept(this, (A)TYPEREQ);
      n.f1.accept(this, argu);
      
      if(is_lambda(type_lhs)){
         // System.out.println("type_lhs:"+type_lhs);
         lambda_exp.arg_type = lambda_type1(type_lhs);
         lambda_exp.ret_type = lambda_type2(type_lhs);
      }

      if(is_lambda(type_lhs)){
         type_rhs = (String) n.f2.accept(this, (A)lambda_exp);
      }
      else type_rhs = (String)n.f2.accept(this, argu);

      n.f3.accept(this, argu);

      boolean matched = false;
      
      // System.out.println("assignment statement: "+type_lhs+","+type_rhs);

      if(type_rhs.equals("this")) type_rhs = curr_class_name;

      if(type_lhs.equals(type_rhs)) matched = true;
      else{
         //check if rhs is subclass of lhs
         matched = type_match(type_lhs, type_rhs);
      }
      
      if(!matched)
         throw new TypeCheckException("Type error");
      return _ret;
   }

