   /**
    * f0 -> PrimaryExpression()
    * f1 -> "."
    * f2 -> Identifier()
    * f3 -> "("
    * f4 -> ( ExpressionList() )?
    * f5 -> ")"
    */
   public R visit(MessageSend n, A argu) {
      R _ret=null;
      ArrayList<String> passed_arg_types = new ArrayList<>();

      String cname = (String)n.f0.accept(this, argu);
      n.f1.accept(this, argu);
      // n.f2.accept(this, null);
      n.f3.accept(this, argu);
      
      // n.f5.accept(this, argu);

      
      if(cname == null ||(!cname.equals("this") && !classes.containsKey(cname))){
         //check if cname is lambda variable

         if(is_lambda(cname)){ 
            if(n.f2.f0.toString().equals("apply")){
               String arg_type = lambda_type1(cname);
               String ret_type = lambda_type2(cname);
               
               real_args = new ArrayList<>();
               real_args.add(new Variable(null,arg_type));
               n.f4.accept(this, (A)passed_arg_types);
               if(passed_arg_types.size() != 1) 
                  throw new TypeCheckException("Type error");
               
               if(type_match(arg_type,passed_arg_types.get(0)))
                  return (R)ret_type;
               else 
                  throw new TypeCheckException("Type error");
            }
            else throw new TypeCheckException("Type error");
         }
         else if(cname!= null && cname.equals(INT)) throw new TypeCheckException("Type error");
         else if(cname!= null && cname.equals(BOOL)) throw new TypeCheckException("Type error");
         else throw new TypeCheckException("Symbol not found");
         
      }

      ClassInfo currc;
      if(cname.equals("this")) currc = classes.get(curr_class_name);
      else currc = classes.get(cname);
      
      String mname = n.f2.f0.toString();
      
      Method m = null;

      if(currc.methods == null || !currc.methods.containsKey(mname)){

         String parname = currc.parent;
         boolean found = false;
         while(parname != null){
            ClassInfo par = classes.get(parname);
            if(par.methods != null && par.methods.containsKey(mname)){
               found = true;
               m = par.methods.get(mname);
               break;
            }
            parname = par.parent;
         }
         if(!found) throw new TypeCheckException("Symbol not found");
      }
      else {
         if(currc.methods.containsKey(mname))
            m = currc.methods.get(mname);
         else 
            throw new TypeCheckException("Symbol not found");
      }

      
      real_args = m.arg_list_ordered;
      if(real_args == null) throw new TypeCheckException("Type error"); 

      n.f4.accept(this, (A)passed_arg_types);

      // System.out.println("method "+mname+" called with args "+passed_arg_types);

      boolean matched = true;
      if(m.arg_list_ordered.size() != passed_arg_types.size()) matched = false;
      else {
         matched = match_method_args(m.arg_list_ordered, passed_arg_types);
      }

      if(!matched) 
         throw new TypeCheckException("Type error");
      return (R)(m.return_type);
   }

   ArrayList<Variable> real_args = null;
   /**
    * f0 -> Expression()
    * f1 -> ( ExpressionRest() )*
    */
   public R visit(ExpressionList n, A argu) {
      R _ret=null;
      
      Lambda_exp le = new Lambda_exp();
      String type;
      ArrayList<String> passed_arg_types = (ArrayList) argu;
      int indx = passed_arg_types.size();
      
      if(real_args == null || real_args.size() <= indx) throw new TypeCheckException("Type error");

      if(real_args.get(indx).type != null && is_lambda(real_args.get(indx).type)){
         le.arg_type = lambda_type1(real_args.get(indx).type);
         le.ret_type = lambda_type2(real_args.get(indx).type);
         // System.out.println("in exp list with lambda type"+le.arg_type+","+le.ret_type);
         type = (String)n.f0.accept(this, (A)le);
      }
      else type = (String)n.f0.accept(this, argu);
      
      passed_arg_types.add(type);

      n.f1.accept(this, (A)passed_arg_types);
      return _ret;
   }

   /**
    * f0 -> ","
    * f1 -> Expression()
    */
   public R visit(ExpressionRest n, A argu) {
      R _ret=null;

      Lambda_exp le = new Lambda_exp();
      String type;
      ArrayList<String> passed_arg_types = (ArrayList) argu;
      int indx = passed_arg_types.size();

      if(real_args.size() <= indx) throw new TypeCheckException("Type error");

      n.f0.accept(this, argu);
      if(real_args.get(indx).type != null && is_lambda(real_args.get(indx).type)){
         le.arg_type = lambda_type1(real_args.get(indx).type);
         le.ret_type = lambda_type2(real_args.get(indx).type);
         // System.out.println("in exp rest with lambda type"+le.arg_type+","+le.ret_type);
         type = (String)n.f1.accept(this, (A)le);
      }
      else type = (String)n.f1.accept(this, argu);
      passed_arg_types.add(type);
      
      return _ret;
   }

