   /**
    * f0 -> <IDENTIFIER>
    */
   public R visit(Identifier n, A argu) {

      if(n.f0.toString().equals("Integer")) return (R)INT;
      if(n.f0.toString().equals("Boolean")) return (R)BOOL;
      
      n.f0.accept(this, argu);
      
      String func = "";
      String final_type = "";
      Lambda_exp le = new Lambda_exp();

      if(argu instanceof String) func = (String)argu;

      boolean islam = (argu instanceof Lambda_exp);
      boolean isarg = false;
      if(islam){
         le = (Lambda_exp)argu;
         isarg = (le.arg!=null) && (le.arg.equals(n.f0.toString()));
      }

      if(islam && isarg){
            return (R)le.arg_type;
      }

      //if identifier matched for rule in primary exp we need to return the type of identifier
      
      if(func.equals(TYPEREQ) || islam) {
         // System.out.println(func);

         String var_name = n.f0.toString();
         ClassInfo currc = classes.get(curr_class_name);
         Method currm = null;
         if(curr_lam_args.containsKey(var_name)){
            return (R)curr_lam_args.get(var_name);
         }
         if(currc.methods != null) 
            currm = currc.methods.get(curr_method_name);

         if(currm != null && currm.arg_list.containsKey(var_name)) 
            final_type = (currm.arg_list.get(var_name).type);

         else if(currm!= null && currm.var_decl.containsKey(var_name)) 
            final_type = (currm.var_decl.get(var_name).type);
         
         else if(currc.variables.containsKey(var_name)) 
            final_type = (currc.variables.get(var_name).type);
         else {
            String parname = currc.parent;
            while(parname != null){
               ClassInfo par = classes.get(parname);
               if(par.variables.containsKey(var_name)) {
                  final_type = (par.variables.get(var_name).type);
                  break;
               }
               parname = par.parent;
            }
         }

         if(final_type.equals("")){
            if(islam){
               if( le.arg == null) return (R)final_type;
               else throw new TypeCheckException("Symbol not found");
            } 
            else{

               throw new TypeCheckException("Symbol not found");
            }   // throw new TypeCheckException("var "+var_name+" not defined"+curr_class_name+","+curr_method_name);
         }
         else{
           return (R) final_type;
         }
      }
      
      return (R)n.f0.toString();
   }

